function validate([n, artifacts, dig]) {
  if (!Number.isInteger(n) || n < 1 || n > 1000) return 'n must be between 1 and 1000.';
  const most = Math.min(n * n, 100000);
  if (!Array.isArray(artifacts) || artifacts.length < 1 || artifacts.length > most) return 'artifacts needs between 1 and min(n^2, 10^5) entries.';
  if (!Array.isArray(dig) || dig.length < 1 || dig.length > most) return 'dig needs between 1 and min(n^2, 10^5) entries.';
  const inside = v => Number.isInteger(v) && v >= 0 && v < n;
  const covered = new Set();
  for (const a of artifacts) {
    if (!Array.isArray(a) || a.length !== 4 || !a.every(inside)) return 'Each artifact is [r1, c1, r2, c2] with values from 0 to n - 1.';
    const [r1, c1, r2, c2] = a;
    if (r1 > r2 || c1 > c2) return 'An artifact needs r1 <= r2 and c1 <= c2.';
    if ((r2 - r1 + 1) * (c2 - c1 + 1) > 4) return 'An artifact covers at most 4 cells.';
    for (let r = r1; r <= r2; r++) for (let c = c1; c <= c2; c++) {
      if (covered.has(r * n + c)) return 'Artifacts must not overlap.';
      covered.add(r * n + c);
    }
  }
  const seen = new Set();
  for (const d of dig) {
    if (!Array.isArray(d) || d.length !== 2 || !d.every(inside)) return 'Each dig entry is [r, c] with values from 0 to n - 1.';
    if (seen.has(d[0] * n + d[1])) return 'The entries of dig must be unique.';
    seen.add(d[0] * n + d[1]);
  }
  return null;
}

