function digArtifacts(n, artifacts, dig) {
  const dug = new Set();
  for (const [row, col] of dig) {
    dug.add(row * n + col);
  }

  let count = 0;
  for (const [r1, c1, r2, c2] of artifacts) {
    let uncovered = true;
    for (let row = r1; row <= r2 && uncovered; row++) {
      for (let col = c1; col <= c2; col++) {
        if (!dug.has(row * n + col)) {
          uncovered = false;
          break;
        }
      }
    }
    if (uncovered) {
      count++;
    }
  }
  return count;
}

