function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const shapes = [[1, 1], [1, 2], [2, 1], [2, 2], [1, 3], [3, 1], [1, 4], [4, 1]];
  const n = size === 'large' ? pick(40, 1000) : pick(1, 5);
  const target = size === 'large' ? 700 : pick(1, Math.min(5, n * n));
  const taken = new Set();
  const artifacts = [];
  for (let tries = 0; artifacts.length < target && tries < target * 30; tries++) {
    const [h, w] = shapes[pick(0, shapes.length - 1)];
    if (h > n || w > n) continue;
    const r1 = pick(0, n - h), c1 = pick(0, n - w);
    const cells = [];
    for (let r = r1; r < r1 + h; r++) for (let c = c1; c < c1 + w; c++) cells.push(r * n + c);
    if (cells.some(k => taken.has(k))) continue;
    cells.forEach(k => taken.add(k));
    artifacts.push([r1, c1, r1 + h - 1, c1 + w - 1]);
  }
  const limit = size === 'large' ? 2000 : n * n;
  const dug = new Set();
  for (const [r1, c1, r2, c2] of artifacts) {
    const mode = rand();
    for (let r = r1; r <= r2; r++) for (let c = c1; c <= c2; c++)
      if ((mode < 0.5 || rand() < 0.5) && dug.size < limit) dug.add(r * n + c);
  }
  const extra = size === 'large' ? 200 : pick(0, 3);
  for (let i = 0; i < extra && dug.size < limit; i++) dug.add(pick(0, n * n - 1));
  if (dug.size === 0) dug.add(pick(0, n * n - 1));
  const keys = [...dug];
  for (let i = keys.length - 1; i > 0; i--) { const j = pick(0, i); [keys[i], keys[j]] = [keys[j], keys[i]]; }
  return [n, artifacts, keys.map(k => [Math.floor(k / n), k % n])];
}
